using System.Diagnostics;

namespace TheTimer.App.Services;

public sealed record SoundOption(string Id, string Name);

/// <summary>Plays a bundled completion sound (Assets/Sounds/&lt;id&gt;.wav) through the first available player; never throws.</summary>
public static class CompletionSound
{
    /// <summary>Bundled sounds, generated by packaging/linux/make_sound.py.</summary>
    public static readonly IReadOnlyList<SoundOption> Options =
    [
        new("chime", "Çan"),
        new("bell", "Zil"),
        new("gong", "Gong"),
    ];

    public static void Play(string id)
    {
        var file = Path.Combine(AppContext.BaseDirectory, "Assets", "Sounds", id + ".wav");
        if (!File.Exists(file))
            file = Path.Combine(AppContext.BaseDirectory, "Assets", "Sounds", "chime.wav");

        // paplay works on the host and inside the Flatpak (pulseaudio socket); canberra is a last resort.
        foreach (var (command, args) in new[] { ("paplay", file), ("pw-play", file), ("canberra-gtk-play", "--id=complete") })
        {
            if (args.StartsWith('/') && !File.Exists(args))
                continue;
            try
            {
                using var process = Process.Start(new ProcessStartInfo(command, args) { UseShellExecute = false });
                if (process is not null)
                    return;
            }
            catch (Exception ex)
            {
                Trace.WriteLine($"Sound player '{command}' failed: {ex.Message}");
            }
        }
    }
}
